from collections import Counter

def transform(grid):
    # The globally most frequent color is the background. Each 3x3 patch
    # reduces to its most frequent non-background color, or background 0
    # when the patch contains no non-background cells.
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[y][x]
                for y in range(r, min(r + 3, h))
                for x in range(c, min(c + 3, w))
                if grid[y][x] != bg
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
